headers.neuralnet.h:
#ifndef __NEURALNET_H__
#define __NEURALNET_H__

namespace nntrainer {

/**
 * @brief Neural Network model class
 * Manages layers, weights, and forward/backward passes
 */
class NeuralNetwork {
public:
  /**
   * @brief Compile the model with loss and optimizer
   * @param loss Loss function
   * @param optimizer Optimizer
   */
  void compile(const std::string &loss, const std::string &optimizer);

  /**
   * @brief Add a layer to the model
   * @param layer Layer to add
   */
  void addLayer(std::shared_ptr<Layer> layer);

  /**
   * @brief Forward pass through all layers
   * @param input Input tensor
   * @return Output tensor
   */
  Tensor forward(const Tensor &input);

  /**
   * @brief Backward pass for training
   * @param loss_gradient Gradient from loss
   */
  void backward(const Tensor &loss_gradient);

  /**
   * @brief Load weights from file
   * @param filepath Path to weights file
   */
  void loadWeights(const std::string &filepath);

  /**
   * @brief Save weights to file
   * @param filepath Path to save weights
   */
  void saveWeights(const std::string &filepath) const;
};

} // namespace nntrainer
#endif

headers.layer.h:
#ifndef __LAYER_H__
#define __LAYER_H__

namespace nntrainer {

/**
 * @brief Base class for all layers
 */
class Layer {
public:
  virtual ~Layer() = default;

  /**
   * @brief Initialize layer parameters
   * @param input_shape Shape of input tensor
   */
  virtual void initialize(const std::vector<size_t> &input_shape) = 0;

  /**
   * @brief Forward pass
   * @param input Input tensor
   * @return Output tensor
   */
  virtual Tensor forward(const Tensor &input) = 0;

  /**
   * @brief Backward pass
   * @param grad_output Gradient w.r.t. output
   * @return Gradient w.r.t. input
   */
  virtual Tensor backward(const Tensor &grad_output) = 0;

  /**
   * @brief Get layer parameters
   * @return Vector of weight/bias tensors
   */
  virtual std::vector<Tensor> getParameters() const = 0;
};

} // namespace nntrainer
#endif

headers.tensor.h:
#ifndef __TENSOR_H__
#define __TENSOR_H__

namespace nntrainer {

/**
 * @brief Multi-dimensional tensor class
 */
class Tensor {
public:
  /**
   * @brief Create a tensor with given shape
   * @param shape Dimensions of the tensor
   */
  explicit Tensor(const std::vector<size_t> &shape);

  /**
   * @brief Get tensor shape
   * @return Vector of dimensions
   */
  std::vector<size_t> shape() const;

  /**
   * @brief Get total number of elements
   */
  size_t size() const;

  /**
   * @brief Fill tensor with random values
   */
  void randomize();

  /**
   * @brief Fill tensor with zeros
   */
  void zero();
};

} // namespace nntrainer
#endif

